namespace SaarOSS.Rechnungsprogramm.Models;
public sealed class Offer
{
 public Guid Id {get;set;}=Guid.NewGuid(); public int DraftNumber{get;set;} public string OfferNumber{get;set;}="";
 public Guid CustomerId{get;set;} public string CustomerNumber{get;set;}=""; public string CustomerName{get;set;}=""; public string CustomerAddressSnapshot{get;set;}=""; public string CompanySnapshot{get;set;}=""; public string TaxModeSnapshot{get;set;}="Regelbesteuerung"; public string SmallBusinessNoticeSnapshot{get;set;}=""; public bool IsSmallBusinessSnapshot=>TaxModeSnapshot=="Kleinunternehmer"; public bool ShowLogoSnapshot{get;set;} public string LogoPngBase64Snapshot{get;set;}=""; public string HeaderLine1Snapshot{get;set;}=""; public string HeaderLine2Snapshot{get;set;}=""; public string HeaderLine3Snapshot{get;set;}=""; public string HeaderLine4Snapshot{get;set;}="";
 public DateTime OfferDate{get;set;}=DateTime.Today; public DateTime ValidUntil{get;set;}=DateTime.Today.AddDays(14); public string IntroText{get;set;}="Gerne bieten wir Ihnen folgende Leistungen an:"; public string ClosingText{get;set;}="Dieses Angebot ist bis zum angegebenen Datum gültig."; public string InternalNote{get;set;}=""; public string Status{get;set;}="Entwurf"; public DateTimeOffset? FinalizedAt{get;set;} public DateTimeOffset? SentAt{get;set;} public DateTimeOffset? AcceptedAt{get;set;} public DateTimeOffset? RejectedAt{get;set;} public Guid? CreatedInvoiceId{get;set;} public List<InvoiceLine> Lines{get;set;}=new(); public DateTimeOffset UpdatedAt{get;set;}=DateTimeOffset.Now;
 public string DraftId=>$"ANG-ENT-{DraftNumber:00000}"; public string DisplayNumber=>string.IsNullOrWhiteSpace(OfferNumber)?(DraftNumber==0?"Nummer beim Speichern":DraftId):OfferNumber; public decimal NetTotal=>Lines.Sum(x=>x.NetAmount); public decimal VatTotal=>Lines.Sum(x=>x.VatAmount); public decimal GrossTotal=>Lines.Sum(x=>x.GrossAmount); public string GrossTotalDisplay=>$"{GrossTotal:N2} €";
}
public sealed class OfferStore{public int NextDraftNumber{get;set;}=1;public string Prefix{get;set;}="AG-";public bool IncludeYear{get;set;}=true;public int Digits{get;set;}=5;public int NextNumber{get;set;}=300;public List<Offer> Offers{get;set;}=new();}
